mapper.select:
SELECT m.id AS merchant_id, m.name, m.address, m.thumbnail_url, m.price, m.latitude, m.longitude, m.rating, CAST(COUNT(r.review_id) AS UNSIGNED) AS review_count, o.noise_level, COALESCE(CAST(SUM(CASE WHEN r.atmosphere = 'QUIET' THEN 1 ELSE 0 END) AS UNSIGNED), 0) AS quiet_review_count, COALESCE(CAST(SUM(CASE WHEN r.atmosphere = 'OPEN' THEN 1 ELSE 0 END) AS UNSIGNED), 0) AS open_review_count, COALESCE(CAST(SUM(CASE WHEN r.atmosphere = 'COLLAB' THEN 1 ELSE 0 END) AS UNSIGNED), 0) AS collab_review_count, CASE WHEN EXISTS ( SELECT 1 FROM bookmarks b WHERE b.users_id = #{userId} AND b.merchants_id = m.id AND b.is_deleted IS NULL ) THEN 1 ELSE 0 END AS bookmarked FROM merchants m INNER JOIN offices o ON o.merchant_id = m.id LEFT JOIN reviews r ON r.merchant_id = m.id AND r.status = 'ACTIVE' WHERE m.category = 'OFFICE' AND m.id IN
#{merchantId}
GROUP BY m.id, m.name, m.address, m.thumbnail_url, m.price, m.latitude, m.longitude, m.rating, o.noise_level ORDER BY m.id ASC

SELECT rr.id, rr.user_id, rr.workation_id, rr.reference_merchant_id, rr.secondary_reference_merchant_id, rr.recommendation_type AS recommendationType, rr.reference_type AS referenceType, rr.meal_type, rr.reference_latitude, rr.reference_longitude, rr.created_at, m.name AS referenceMerchantName, m2.name AS secondaryReferenceMerchantName FROM recommendation_requests rr LEFT JOIN merchants m ON m.id = rr.reference_merchant_id LEFT JOIN merchants m2 ON m2.id = rr.secondary_reference_merchant_id WHERE rr.user_id = #{userId} AND rr.workation_id = #{workationId} AND rr.recommendation_type = 'OFFICE'
AND rr.reference_merchant_id = #{referenceMerchantId}
ORDER BY rr.created_at DESC, rr.id DESC LIMIT 1

SELECT rr.id, rr.user_id, rr.workation_id, rr.reference_merchant_id, rr.secondary_reference_merchant_id, rr.recommendation_type AS recommendationType, rr.reference_type AS referenceType, rr.meal_type, rr.reference_latitude, rr.reference_longitude, rr.created_at, m.name AS referenceMerchantName, m2.name AS secondaryReferenceMerchantName FROM recommendation_requests rr LEFT JOIN merchants m ON m.id = rr.reference_merchant_id LEFT JOIN merchants m2 ON m2.id = rr.secondary_reference_merchant_id WHERE rr.user_id = #{userId} AND rr.workation_id = #{workationId} AND rr.recommendation_type = 'OFFICE' AND rr.created_at >= #{startAt} AND rr.created_at < #{endAt}
AND rr.reference_merchant_id = #{referenceMerchantId}
ORDER BY rr.created_at DESC, rr.id DESC LIMIT 1

SELECT COUNT(1)
FROM recommendation_results
WHERE recommendation_request_id = #{recommendationRequestId}

SELECT rr.id AS recommendation_result_id, rr.recommendation_request_id AS recommendation_request_id, rr.ranking, rr.price_score, rr.preference_score, rr.accessibility_score, rr.rating_score, rr.total_score, m.id AS merchant_id, m.name, m.address, m.thumbnail_url, m.price, m.rating, o.noise_level, CAST(COUNT(r.review_id) AS UNSIGNED) AS review_count, COALESCE(CAST(SUM(CASE WHEN r.atmosphere = 'QUIET' THEN 1 ELSE 0 END) AS UNSIGNED), 0) AS quiet_review_count, COALESCE(CAST(SUM(CASE WHEN r.atmosphere = 'OPEN' THEN 1 ELSE 0 END) AS UNSIGNED), 0) AS open_review_count, COALESCE(CAST(SUM(CASE WHEN r.atmosphere = 'COLLAB' THEN 1 ELSE 0 END) AS UNSIGNED), 0) AS collab_review_count, rr.calculated_at, CAST(m.latitude AS DECIMAL(10, 8)) AS latitude, CAST(m.longitude AS DECIMAL(11, 8)) AS longitude, CASE WHEN EXISTS ( SELECT 1 FROM bookmarks b WHERE b.users_id = #{userId} AND b.merchants_id = m.id AND b.is_deleted IS NULL ) THEN 1 ELSE 0 END AS bookmarked FROM recommendation_results rr JOIN recommendation_requests rec_request ON rec_request.id = rr.recommendation_request_id JOIN workations w ON w.id = rec_request.workation_id JOIN merchants m ON m.id = rr.merchant_id JOIN offices o ON o.merchant_id = m.id LEFT JOIN reviews r ON r.merchant_id = m.id AND r.status = 'ACTIVE' WHERE rr.recommendation_request_id = #{recommendationRequestId} AND EXISTS ( SELECT 1 FROM reservation_products rp JOIN product_daily_inventories pdi ON pdi.product_id = rp.id WHERE rp.merchant_id = rr.merchant_id AND rp.product_detail_type IN ('OFFICE_SEAT', 'MEETING_ROOM') AND pdi.inventory_date >= w.start_date AND pdi.inventory_date <= w.end_date GROUP BY rp.id HAVING COUNT(DISTINCT pdi.inventory_date) = DATEDIFF(w.end_date, w.start_date) + 1 AND MIN(CASE WHEN pdi.is_available = 1 AND pdi.remaining_capacity >= 1 THEN 1 ELSE 0 END) = 1 )
AND ( rr.ranking > #{cursorRanking} OR ( rr.ranking = #{cursorRanking} AND rr.id > #{cursorId} ) )
GROUP BY rr.id, rr.recommendation_request_id, rr.ranking, rr.price_score, rr.preference_score, rr.accessibility_score, rr.rating_score, rr.total_score, m.id, m.name, m.address, m.thumbnail_url, m.price, m.rating, o.noise_level, rr.calculated_at, m.latitude, m.longitude, w.start_date, w.end_date ORDER BY rr.ranking ASC, rr.id ASC LIMIT #{size}
